// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.diimport timber.log.Timberimport com.roshan.persona.cognitive.decision.DecisionMakerimport com.roshan.persona.cognitive.engine.ClarificationEngineimport com.roshan.persona.cognitive.engine.ConfidenceModulatorimport com.roshan.persona.cognitive.engine.UncertaintyAwarenessimport com.roshan.persona.cognitive.execution.PlanExecutorBridgeimport com.roshan.persona.cognitive.execution.ReasoningCacheimport com.roshan.persona.cognitive.execution.ReasoningTraceStoreimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.Constraintimport com.roshan.persona.cognitive.model.PlanExecutionResultimport com.roshan.persona.cognitive.model.ReasoningTraceimport com.roshan.persona.cognitive.model.SubTaskimport com.roshan.persona.cognitive.model.UncertaintyActionimport com.roshan.persona.cognitive.planner.TaskPlannerimport com.roshan.persona.cognitive.reasoning.ReasoningEngineimport com.roshan.persona.cognitive.solver.ProblemSolverimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.persona.core.PersonaProfileimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Cognitive Facade (Module 7 v2 — Step 7.8 FINAL). * * The single entry point for the Cognitive Layer. Brain (Module 2) and * UI (Module 16) talk to this one class — everything else in * :feature:cognitive is an implementation detail. * * ## Public API * *  - [process] — main entry: routes a query through the full cognitive *    pipeline (clarify → plan → reason → decide/solve → execute). *  - [getCachedTrace] — check reasoning cache (skip LLM if hit). *  - [getTraceHistory] — recent reasoning traces (for UI). *  - [getStoredTrace] — revisit why NOUS recommended X. *  - [deleteStoredTrace] — user "forget why you recommended X". * * ## Pipeline flow (per strategy v2 §"Architecture") * * ``` * 1. Check ReasoningCache → if hit, return cached trace (< 50ms). * 2. ClarificationEngine.checkClarification → if ambiguous, return questions. * 3. TaskPlanner.decompose → sub-tasks + dependency graph. * 4. ReasoningEngine.reason → chain-of-thought + self-correction. * 5. UncertaintyAwareness.handle → if low confidence, defer/admit. * 6. DecisionMaker.decide OR ProblemSolver.solve → decision/solution. * 7. ConfidenceModulator.modulate → wrap with persona tone. * 8. ReasoningCache.store + ReasoningTraceStore.store → cache + persist. * 9. Return ReasoningTrace. * ``` * * ## Integration with Brain * * Brain's Layer 5 (AgenticOrchestrator) detects `Intent.MultiStep` and * calls [process] instead of running the reactive ReAct loop directly. * The Cognitive Layer creates a plan, reasons through it, and hands * execution to the Agentic Layer via [PlanExecutorBridge]. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§Architecture</a> */@Singletonclass CognitiveFacade @Inject constructor(    private val clarificationEngine: ClarificationEngine,    private val taskPlanner: TaskPlanner,    private val reasoningEngine: ReasoningEngine,    private val decisionMaker: DecisionMaker,    private val problemSolver: ProblemSolver,    private val uncertaintyAwareness: UncertaintyAwareness,    private val confidenceModulator: ConfidenceModulator,    private val reasoningCache: ReasoningCache,    private val reasoningTraceStore: ReasoningTraceStore,    private val planExecutorBridge: PlanExecutorBridge,    private val preferenceLearner: com.roshan.persona.cognitive.execution.PreferenceLearner,    private val config: CognitiveConfig = CognitiveConfig(),) {    /**     * Process a cognitive query through the full pipeline.     *     * @param query the user's query ("Plan a 3-day Goa trip under ₹15K").     * @param persona the active persona (affects reasoning style + tone).     * @param userId the user's ID (for caching).     * @param constraints constraints the answer must satisfy.     * @param availableToolIds set of available tool IDs (for tool-aware planning).     * @param context additional context (memory recall, ambient snapshot).     * @return a [CognitiveResult] — either a reasoning trace, clarification     *         questions, or an error.     */    suspend fun process(        query: String,        persona: PersonaProfile,        userId: String,        constraints: List<Constraint> = emptyList(),        availableToolIds: Set<String> = emptySet(),        context: String = "",    ): CognitiveResult {        Timber.tag(TAG).i("Processing: query='$query', persona=${persona.id}")        // 1. Check cache — if hit, return instantly.        reasoningCache.lookup(query, userId, persona.id)?.let { cached ->            Timber.tag(TAG).i("Cache hit — returning cached trace.")            return CognitiveResult.Trace(cached, fromCache = true)        }        // 2. Check clarification — if ambiguous, return questions.        val clarification = clarificationEngine.checkClarification(query, persona)        if (clarification != null && clarification.isNotEmpty()) {            Timber.tag(TAG).i("Clarification needed: ${clarification.size} questions.")            return CognitiveResult.NeedsClarification(clarification)        }        // 3. Plan — decompose into sub-tasks.        val plan = taskPlanner.decompose(query, availableToolIds)        val subTasks: List<SubTask>? = plan?.subTasks        // 4. Reason — chain-of-thought + self-correction.        var trace = reasoningEngine.reason(            query = query,            persona = persona,            constraints = constraints,            subTasks = subTasks,            context = context,        )        // 5. Uncertainty check — if low confidence, defer.        val uncertaintyAction = uncertaintyAwareness.handle(trace.confidence, query)        if (uncertaintyAction !is UncertaintyAction.Answer) {            Timber.tag(TAG).i("Uncertainty: $uncertaintyAction — returning with low confidence.")            // Still return the trace, but with the uncertainty action for the caller.            return CognitiveResult.Uncertain(trace, uncertaintyAction)        }        // 6. Decision / Solve — multi-criteria analysis or pattern matching        //    (Strategy §8.1 step 6 — was previously skipped, audit Task ID: audit-m8-cognitive P0 fix).        //    Trigger when query looks like a decision ("vs", "compare", "which",        //    "better") OR like a problem ("how do i", "fix", "solve", "troubleshoot").        val lowerQuery = query.lowercase().trim()        val isDecisionQuery = DECISION_PATTERNS.any { it.containsMatchIn(lowerQuery) }        val isProblemQuery = PROBLEM_PATTERNS.any { it.containsMatchIn(lowerQuery) }        if (isDecisionQuery) {            // Extract option names from the query (simple split on "vs"/"or"/"and").            val optionNames = lowerQuery                .split(Regex("\\s+(?:vs\\.?|versus|or|and)\\s+"))                .map { it.replace(Regex("^[^a-z0-9]+|[^a-z0-9]+$"), "").trim() }                .filter { it.isNotEmpty() && it.length < 80 }                .take(8)            if (optionNames.size >= 2) {                Timber.tag(TAG).i("Step 6: routing to DecisionMaker for ${optionNames.size} options.")                val decision = decisionMaker.decide(                    query = query,                    optionNames = optionNames,                    userPreferences = emptyList(),                    personaId = persona.id,                )                if (decision != null) {                    // Augment trace with the recommendation + rationale.                    val decisionBlock = buildString {                        appendLine("**Recommendation: ${decision.recommendation.name}**")                        appendLine()                        appendLine(decision.rationale)                        if (decision.recommendation.pros.isNotEmpty()) {                            appendLine()                            appendLine("Pros: ${decision.recommendation.pros.joinToString(", ")}")                        }                        if (decision.recommendation.cons.isNotEmpty()) {                            appendLine("Cons: ${decision.recommendation.cons.joinToString(", ")}")                        }                    }                    trace = trace.copy(                        finalAnswer = decisionBlock + "\n\n" + trace.finalAnswer,                        confidence = maxOf(trace.confidence, decision.confidence),                    )                }            }        } else if (isProblemQuery) {            Timber.tag(TAG).i("Step 6: routing to ProblemSolver for pattern matching + constraint satisfaction.")            val solution = problemSolver.solve(                problem = query,                constraints = constraints,                context = context,            )            if (solution != null && solution.confidence > trace.confidence) {                trace = trace.copy(                    finalAnswer = solution.solution,                    confidence = solution.confidence,                )            }        }        // 7. Confidence modulation — wrap answer with persona tone.        val modulatedAnswer = confidenceModulator.modulate(            confidence = trace.confidence,            recommendation = trace.finalAnswer,            personaId = persona.id,        )        trace = trace.copy(finalAnswer = modulatedAnswer)        // 8. Cache + store.        reasoningCache.store(query, userId, trace, personaId = persona.id)        reasoningTraceStore.store(query, trace)        // 9. Return.        Timber.tag(TAG).i("Processing complete: confidence=${trace.confidence}, steps=${trace.steps.size}.")        return CognitiveResult.Trace(trace, fromCache = false)    }    private companion object {        private const val TAG = "CognitiveFacade"        // Patterns that signal a decision-style query.        private val DECISION_PATTERNS: List<Regex> = listOf(            Regex("\\bvs\\.?\\b"),            Regex("\\bversus\\b"),            Regex("\\bcompare\\b"),            Regex("\\bwhich\\b.*\\bbetter\\b"),            Regex("\\bbetter\\b.*\\bor\\b"),            Regex("\\bbest\\b.*\\b(for|to)\\b"),            Regex("\\bpick\\b.*\\bbetween\\b"),            Regex("\\bchoose\\b.*\\bbetween\\b"),            Regex("\\brecommend\\b"),        )        // Patterns that signal a problem-solving query.        private val PROBLEM_PATTERNS: List<Regex> = listOf(            Regex("\\bhow\\s+do\\s+i\\b"),            Regex("\\bhow\\s+to\\b"),            Regex("\\bhow\\s+can\\s+i\\b"),            Regex("\\bfix\\b"),            Regex("\\bsolve\\b"),            Regex("\\btroubleshoot\\b"),            Regex("\\bdebug\\b"),            Regex("\\bresolve\\b"),            Regex("\\bworkaround\\b"),            Regex("\\berror\\b"),            Regex("\\bnot\\s+working\\b"),            Regex("\\bbroken\\b"),        )    }    /**     * Execute a task plan via the Agentic Layer (Brain Layer 5).     *     * Called when the user confirms a plan or when the Brain needs to     * execute sub-tasks after reasoning.     *     * @param plan the task plan to execute.     * @param persona the active persona.     * @return the execution result.     */    suspend fun executePlan(        plan: com.roshan.persona.cognitive.model.TaskPlan,        persona: PersonaProfile,    ): PlanExecutionResult {        Timber.tag(TAG).i("Executing plan: ${plan.subTasks.size} sub-tasks.")        return planExecutorBridge.execute(plan, persona)    }    /**     * Get cached trace for (query, userId) — without processing.     *     * Returns null if not cached or expired.     */    fun getCachedTrace(query: String, userId: String): ReasoningTrace? {        return reasoningCache.lookup(query, userId, personaId = "default")    }    /**     * Get recent reasoning traces (for UI history).     *     * @param limit max results (default 20).     * @return list of stored traces, most-recent-first.     */    fun getTraceHistory(limit: Int = 20): List<com.roshan.persona.cognitive.model.StoredReasoningTrace> {        return reasoningTraceStore.getRecent(limit)    }    /**     * Get a specific stored trace by ID (for "why did you recommend X?").     */    fun getStoredTrace(traceId: String): com.roshan.persona.cognitive.model.StoredReasoningTrace? {        return reasoningTraceStore.get(traceId)    }    /**     * Search stored traces by query ("show me why you recommended the train").     */    fun searchTraces(query: String, limit: Int = 10): List<com.roshan.persona.cognitive.model.StoredReasoningTrace> {        return reasoningTraceStore.search(query, limit)    }    /**     * Delete a stored trace (user: "forget why you recommended X").     *     * @return true if a trace was deleted.     */    fun deleteStoredTrace(traceId: String): Boolean {        return reasoningTraceStore.delete(traceId)    }    /**     * Record user feedback on a trace.     *     * Feeds the PreferenceLearner so future queries on the same topic get     * adjusted confidence thresholds (strategy §8 "Feedback loop").     */    fun recordTraceFeedback(        traceId: String,        feedback: com.roshan.persona.cognitive.model.UserFeedback,        correctionNote: String? = null,    ) {        reasoningTraceStore.recordFeedback(traceId, feedback, correctionNote)        // Also feed the PreferenceLearner — extract the original query from the trace.        val trace = reasoningTraceStore.getRecent(500).find { it.traceId == traceId }        if (trace != null) {            preferenceLearner.recordFeedback(trace.userQuery, feedback)        }    }}// ──────────────────────────────────────────────────────────────────────────/** * Result of [CognitiveFacade.process]. * * - [CognitiveResult.Trace] — reasoning complete, here's the trace. * - [CognitiveResult.NeedsClarification] — ambiguous query, here are questions. * - [CognitiveResult.Uncertain] — low confidence, here's the action to take. */sealed interface CognitiveResult {    data class Trace(        val trace: ReasoningTrace,        val fromCache: Boolean,    ) : CognitiveResult    data class NeedsClarification(        val questions: List<com.roshan.persona.cognitive.model.ClarificationQuestion>,    ) : CognitiveResult    data class Uncertain(        val trace: ReasoningTrace,        val action: UncertaintyAction,    ) : CognitiveResult}